    "method": "Four equal nominal pillars: Adoption, Monetization, Hyperscalers and Infrastructure. Monetization allocates 15% of the core to Ramp business spending, 5% to consumer card spending, and 5% to released recognized revenue shared by eligible labs. Missing constituent weight is redistributed proportionally within its pillar. If an entire pillar is unavailable, the available pillars share the index equally. The score is unavailable only when no scoring constituent is available. Context indicators carry zero weight.",
